opencat.script:
/* local = source script time + OFFSET (HEYGEN_START 5.58 − 6.20) */
var OFFSET = -0.62;

/* ── phone: procedural 2D approximation of the Three.js GLB ────────
   Projected centre/size: projY(wy,depth) = 540 − wy·FOCAL/depth,
   FOCAL = 540/tan(17°) ≈ 1766.6; phone world height 3.2. */
var FOCAL = 540.0 / Math.tan(17 * Math.PI / 180);
function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }
function lerp(a, b, t) { return a + (b - a) * clamp01(t); }
function pow2out(t) { return 1 - Math.pow(1 - clamp01(t), 2); }
function pow3out(t) { return 1 - Math.pow(1 - clamp01(t), 3); }
function pow3in(t)  { return Math.pow(clamp01(t), 3); }
function expoOut(t) { t = clamp01(t); return t >= 1 ? 1 : 1 - Math.pow(2, -10 * t); }
function power1out(t) { return clamp01(t); }
var st = Math.max(0, ctx.global.time);

var phY, phRY, cZ, phRZ = 0.006;
// S.phY −3.45→0.02 expo.out @0.08 source → local −0.54, dur 0.95
phY = st < -0.54 ? -3.45 : lerp(-3.45, 0.02, expoOut((st + 0.54) / 0.95));
// S.cZ 6.6→6.35 breatheEase @0.18 → local −0.44, dur 0.78
cZ = st < -0.44 ? 6.6 : lerp(6.6, 6.35, pow3out((st + 0.44) / 0.78));
// S.phRY PI−0.035 until spin @2.2 → local 1.58; PI→5PI over 1.73
if (st < 1.58) phRY = Math.PI - 0.035;
else if (st < 3.31) phRY = Math.PI - 0.035 + Math.PI * 4 * ((st - 1.58) / 1.73);
else phRY = Math.PI * 5 - 0.035;
// push-in @3.43 → local 2.81: phRZ→PI/2, cZ→3.85
if (st >= 2.81) {
  var pk = pow3in((st - 2.81) / 0.85);
  phRZ = lerp(0.006, Math.PI / 2, pk);
  cZ = lerp(6.35, 3.85, pk);
}
var phoneH = 3.2 * FOCAL / cZ;
var phoneW = phoneH * (390 / 844);
var cy = 540 - phY * FOCAL / cZ;
var phoneNode = ctx.getNode('phone');
// exit @4.04 → local 3.42: x→−1220 expo.out 0.53, opacity→0 0.18
var exitX = st < 3.42 ? 0 : -1220 * expoOut((st - 3.42) / 0.53);
phoneNode.left(960 + exitX - phoneW * 0.5);
phoneNode.top(cy - phoneH * 0.5);
phoneNode.width(phoneW);
phoneNode.height(phoneH);
var sx = Math.abs(Math.cos(phRY));         // flat body foreshortens on spin
phoneNode.scaleX(sx < 0.05 ? 0.05 : sx);
phoneNode.rotate(phRZ * 180 / Math.PI);
var entryOp = pow2out((st + 0.54) / 0.5);
var exitOp = st < 3.42 ? 1 : 1 - clamp01((st - 3.42) / 0.18);
phoneNode.opacity(clamp01(entryOp) * exitOp);
// S.scroll 0→0.9 power1.out @2.05 → local 1.43, dur 2.45; page scrolls
var scroll = st < 1.43 ? 0 : 0.9 * power1out((st - 1.43) / 2.45);
ctx.getNode('phone-page').top(-scroll * 480);

/* ── decl: bg video, finger, prompt, typing, send, copy ─────────── */
var T = ctx.timeline();
// bg-video already faded in at abs 5.58 (before this act's 6.20 window)
T.set('bg-video', { opacity: 1 }, 0);

// finger: left 1260→805, top 1220→532 power3.out @0.30 dur 0.82
T.set('finger', { left: 1260, top: 1220, rotation: -75, opacity: 0 }, 0);
T.to('finger', { opacity: 1, duration: 0.2, ease: 'power1.out' }, 0.1);
T.to('finger', { left: 805, top: 532, duration: 0.82, ease: 'power3.out' }, 0.30);
// then top→−1900 power3.inOut @1.23 dur 0.68; opacity 0 @1.93
T.to('finger', { top: -1900, duration: 0.68, ease: 'power3.inOut' }, 1.23);
T.set('finger', { opacity: 0 }, 1.93);

// prompt-scene @3.46: visible, x 620→0 blur→0 0.27 power2.out, opacity→1 0.48
T.set('prompt-scene', { opacity: 0, x: 620, filter: 'blur(18px)' }, 0);
T.to('prompt-scene', { x: 0, filter: 'blur(0px)', duration: 0.27, ease: 'power2.out' }, 3.46);
T.to('prompt-scene', { opacity: 1, duration: 0.48, ease: 'power2.out' }, 3.46);
T.set('prompt-app', { x: 560, y: -120, scale: 3.15, transformOrigin: '50% 92%' }, 0);
// typing "npx hyperframes add iphone-canvas" @3.51 dur 0.9 — reveal glyphs
var cp = ctx.splitText('prompt-command', { type: 'chars' });
for (var i = 0; i < cp.length; i++) {
  T.set(cp[i], { opacity: 0 }, 0);
  T.set(cp[i], { opacity: 1 }, 3.51 + (i / cp.length) * 0.9);
}
T.set('prompt-caret', { opacity: 1 }, 3.46);
// caret stops typing @3.51+0.9=4.41
// blink @6.25 → local 5.63 (repeat 3 yoyo steps)
T.to('prompt-caret', { opacity: 0, duration: 0.12, repeat: 3, yoyo: true, ease: 'steps(1)' }, 5.63);
T.set('prompt-caret', { opacity: 0 }, 4.41);
// camera pan x→−1260 @3.51 dur 1.78 power1.in (accelerating)
T.to('prompt-app', { x: -1260, duration: 1.78, ease: 'power1.in' }, 3.51);
// meta opacity→1 @4.28 dur 0.18
T.to('prompt-meta', { opacity: 1, duration: 0.18, ease: 'power1.out' }, 4.28);
// topbar + command + meta fade/blur/scale0.86 @4.97 dur 0.2 power3.inOut
T.to('prompt-topbar', { opacity: 0, filter: 'blur(16px)', scale: 0.86, duration: 0.2, ease: 'power3.inOut', transformOrigin: '50% 50%' }, 4.97);
T.to('prompt-command', { opacity: 0, filter: 'blur(16px)', duration: 0.2, ease: 'power3.inOut' }, 4.97);
T.to('prompt-meta', { opacity: 0, filter: 'blur(16px)', duration: 0.2, ease: 'power3.inOut' }, 4.97);
// composer bg → transparent @4.97 dur 0.2
T.to('prompt-composer', { backgroundColor: 'rgba(255,255,255,0)', borderColor: 'rgba(229,224,209,0)', duration: 0.2, ease: 'power3.inOut' }, 4.97);
// send: y→−95 @5.07 dur 0.22 power2.out; scale→3 0.22 power3.out
T.set('prompt-send', { x: 0, y: 0, scale: 1 }, 0);
T.to('prompt-send', { y: -95, duration: 0.22, ease: 'power2.out' }, 5.07);
T.to('prompt-send', { scale: 3, duration: 0.22, ease: 'power3.out', transformOrigin: '50% 50%' }, 5.07);
// cursor @5.18 x280 y210 op1 0.28 power3.out; @5.48 x26 y38 0.46 power3.inOut
T.set('click-cursor', { x: 500, y: 620, scale: 0.95, opacity: 0, rotation: -6 }, 0);
T.to('click-cursor', { x: 280, y: 210, opacity: 1, duration: 0.28, ease: 'power3.out' }, 5.18);
T.to('click-cursor', { x: 26, y: 38, duration: 0.46, ease: 'power3.inOut' }, 5.48);
// click: send 3→2.62 (0.08 power2.in) @5.88; →3.12 back.out(2.2) 0.16 @5.97
T.to('prompt-send', { scale: 2.62, duration: 0.08, ease: 'power2.in' }, 5.88);
T.to('click-cursor', { scale: 0.82, duration: 0.08, ease: 'power2.in' }, 5.88);
T.to('prompt-send', { scale: 3.12, duration: 0.16, ease: 'back.out(2.2)' }, 5.97);
T.to('click-cursor', { scale: 0.95, duration: 0.16, ease: 'back.out(2.2)' }, 5.97);
// exit @6.06: send y→−260, cursor y→−165, blur 8, opacity 0 dur 0.28 power2.in
T.to('prompt-send', { y: -260, filter: 'blur(8px)', opacity: 0, duration: 0.28, ease: 'power2.in' }, 6.06);
T.to('click-cursor', { y: -165, filter: 'blur(8px)', opacity: 0, duration: 0.28, ease: 'power2.in' }, 6.06);
// game-change @6.34: y 220→0 blur→0 0.46 expo.out; opacity→1 0.24 power1.out
T.set('game-change-copy', { y: 220, opacity: 0, filter: 'blur(8px)' }, 0);
T.to('game-change-copy', { y: 0, filter: 'blur(0px)', duration: 0.46, ease: 'expo.out', transformOrigin: '50% 50%' }, 6.34);
T.to('game-change-copy', { opacity: 1, duration: 0.24, ease: 'power1.out' }, 6.34);
